@page "/board"
@using sv_5b30fd0b9a034314abc9a6aa8800ef28
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">@errorMessage</div>
}
else if (allTasks is null)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><strong>Total</strong><br />@allTasks.Count</div></div>
        <div class="col"><div class="card text-center p-2"><strong>To Do</strong><br />@GetColumnTasks("To Do").Count</div></div>
        <div class="col"><div class="card text-center p-2"><strong>In Progress</strong><br />@GetColumnTasks("In Progress").Count</div></div>
        <div class="col"><div class="card text-center p-2"><strong>Done</strong><br />@GetColumnTasks("Done").Count</div></div>
        <div class="col"><div class="card text-center p-2 text-danger"><strong>Overdue</strong><br />@allTasks.Count(t => t.DueDate < DateTime.Today)</div></div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..." @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @foreach (var column in columns)
        {
            var colTasks = GetFilteredColumnTasks(column);
            var colIndex = Array.IndexOf(columns, column);

            <div class="col-md-4">
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@colTasks.Count</span>
                    </div>
                    <div class="card-body p-2" style="min-height: 200px;">
                        @foreach (var task in colTasks)
                        {
                            <div class="card mb-2">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="card-text mb-1 text-muted small">@task.Assignee</p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm" @onclick="() => MoveTask(task.Id, columns[colIndex - 1])" disabled="@isProcessing">
                                                &larr; Move Left
                                            </button>
                                        }
                                        @if (colIndex < columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm" @onclick="() => MoveTask(task.Id, columns[colIndex + 1])" disabled="@isProcessing">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingToColumn == column)
                        {
                            <div class="card border-primary mb-2">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Title" @bind="newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee" @bind="newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-1" @bind="newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm" @onclick="SaveNewTask" disabled="@isProcessing">Save</button>
                                        <button class="btn btn-secondary btn-sm" @onclick="CancelAdd" disabled="@isProcessing">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => StartAdd(column)" disabled="@isProcessing">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<TaskItem>? allTasks;
    private string? errorMessage;
    private string searchText = string.Empty;
    private bool isProcessing;

    private readonly string[] columns = { "To Do", "In Progress", "Done" };

    // Add-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => allTasks?.Where(t => t.Status == status).ToList() ?? new();

    private List<TaskItem> GetFilteredColumnTasks(string status)
        => GetColumnTasks(status)
            .Where(t => string.IsNullOrWhiteSpace(searchText)
                || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        isProcessing = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            isProcessing = false;
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => addingToColumn = null;

    private async Task SaveNewTask()
    {
        if (string.IsNullOrWhiteSpace(newTitle) || addingToColumn is null)
            return;

        isProcessing = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            if (created.Status != addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, addingToColumn);
            }
            allTasks = await TaskService.GetAllTasksAsync();
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isProcessing = false;
        }
    }
}

